import test from 'node:test';import assert from 'node:assert/strict';import {ActionWindowController} from '../src/poc02/action-window.js';
const plan={planId:'P',caseId:'C',goal:'g',expectedResultRef:'B',steps:[{stepId:'1',action:'CLICK' as const,target:'a'},{stepId:'2',action:'FILL' as const,target:'b'}]};
test('only previous current next are exposed',()=>{const c=new ActionWindowController(plan);const w=c.currentWindow();assert.equal(w.previous,null);assert.equal(w.current.stepId,'1');assert.equal(w.next?.stepId,'2');assert.equal(w.actionBudget,1);});
test('out of order action is rejected',()=>{const c=new ActionWindowController(plan);assert.throws(()=>c.begin('2'),/OUT_OF_ORDER_ACTION/);});
test('failed action does not advance cursor',()=>{const c=new ActionWindowController(plan);c.begin('1');c.complete('1','FAILED');assert.equal(c.currentWindow().current.stepId,'1');});

import fs from 'node:fs/promises';
import path from 'node:path';

export async function generateScriptPackage(dir:string):Promise<string>{
  await fs.mkdir(path.join(dir,'tests'),{recursive:true});
  await fs.mkdir(path.join(dir,'expected'),{recursive:true});
  const spec = `import { test, expect } from '@playwright/test';
import { transferHtml } from '../../../src/shared/test-page.js';

test('generated transfer regression', async ({ page }) => {
  await page.route('https://bank.test/api/v1/transfers', async route => {
    const payload = route.request().postDataJSON();
    const ok = payload?.beneficiary === 'customer.bob' && payload?.amount?.value === '100.00';
    await route.fulfill({status:ok?201:422,contentType:'application/json',body:JSON.stringify(ok?{id:'TR-P0C-001',status:'SETTLED',correlationId:'CORR-P0C'}:{status:'FAILED'})});
  });
  await page.setContent(transferHtml);
  await test.step('select beneficiary', async()=>{ await page.getByTestId('transfer-beneficiary').selectOption('customer.bob'); });
  await test.step('fill amount', async()=>{ await page.getByTestId('transfer-amount').fill('100.00'); });
  await test.step('submit', async()=>{
    const responsePromise=page.waitForResponse(r=>r.url().includes('/api/v1/transfers'));
    await page.getByTestId('transfer-confirm').click();
    expect((await responsePromise).status()).toBe(201);
  });
  await expect(page.getByTestId('transfer-status')).toHaveText('转账成功');
});
`;
  await fs.writeFile(path.join(dir,'tests','generated.spec.ts'),spec,'utf8');
  await fs.writeFile(path.join(dir,'expected','baseline.json'),JSON.stringify({visibleText:'转账成功',networkStatus:201},null,2),'utf8');
  await fs.writeFile(path.join(dir,'manifest.json'),JSON.stringify({artifactId:'SCRIPT-P04',caseId:'REG-P04',entrySpec:'tests/generated.spec.ts',baseline:'expected/baseline.json'},null,2),'utf8');
  return path.join(dir,'tests','generated.spec.ts');
}
